1	// Dependency-free page extraction. Good enough for a reading queue: fetch the
2	// HTML, pull the title / description / og-image / favicon, and reduce the body
3	// to plain text for the summariser. Not a full readability port — it strips
4	// chrome heuristically and caps length.
5	
6	export type Extracted = {
7	  title?: string;
8	  description?: string;
9	  ogImage?: string;
10	  favicon?: string;
11	  text: string;
12	  lang?: string;
13	  readMinutes?: number;
14	};
15	
16	const UA = "Mozilla/5.0 (compatible; HazyNoteBot/1.0; +https://github.com/hazy-note)";
17	
18	function decodeEntities(s: string): string {
19	  return s
20	    .replace(/&amp;/g, "&")
21	    .replace(/&lt;/g, "<")
22	    .replace(/&gt;/g, ">")
23	    .replace(/&quot;/g, '"')
24	    .replace(/&#39;|&apos;/g, "'")
25	    .replace(/&nbsp;/g, " ")
26	    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
27	    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)));
28	}
29	
30	function meta(html: string, patterns: RegExp[]): string | undefined {
31	  for (const re of patterns) {
32	    const m = html.match(re);
33	    if (m?.[1]) return decodeEntities(m[1].trim());
34	  }
35	  return undefined;
36	}
37	
38	function absolutize(href: string | undefined, base: string): string | undefined {
39	  if (!href) return undefined;
40	  try {
41	    return new URL(href, base).toString();
42	  } catch {
43	    return undefined;
44	  }
45	}
46	
47	export function htmlToText(html: string): string {
48	  let body = html;
49	  const article = body.match(/<article[\s>][\s\S]*?<\/article>/i);
50	  const main = body.match(/<main[\s>][\s\S]*?<\/main>/i);
51	  if (article) body = article[0];
52	  else if (main) body = main[0];
53	
54	  return decodeEntities(
55	    body
56	      .replace(/<script[\s\S]*?<\/script>/gi, " ")
57	      .replace(/<style[\s\S]*?<\/style>/gi, " ")
58	      .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
59	      .replace(/<!--[\s\S]*?-->/g, " ")
60	      .replace(/<(nav|header|footer|aside|form)[\s\S]*?<\/\1>/gi, " ")
61	      .replace(/<\/(p|div|section|h[1-6]|li|br|tr)>/gi, "\n")
62	      .replace(/<[^>]+>/g, " ")
63	  )
64	    .replace(/[ \t\f\v]+/g, " ")
65	    .replace(/\n\s*\n\s*\n+/g, "\n\n")
66	    .split("\n")
67	    .map((l) => l.trim())
68	    .filter(Boolean)
69	    .join("\n")
70	    .trim();
71	}
72	
73	/** Fetch a URL and extract its readable content. Throws on network/HTTP error. */
74	export async function fetchAndExtract(url: string): Promise<Extracted> {
75	  const ctrl = new AbortController();
76	  const timer = setTimeout(() => ctrl.abort(), 15_000);
77	  let res: Response;
78	  try {
79	    res = await fetch(url, {
80	      signal: ctrl.signal,
81	      redirect: "follow",
82	      headers: { "user-agent": UA, accept: "text/html,application/xhtml+xml" },
83	    });
84	  } finally {
85	    clearTimeout(timer);
86	  }
87	  if (!res.ok) throw new Error(`fetch ${res.status} for ${url}`);
88	
89	  const finalUrl = res.url || url;
90	  const ctype = res.headers.get("content-type") ?? "";
91	  if (!ctype.includes("html") && !ctype.includes("xml")) {
92	    // PDF, video page behind JS, etc. — nothing to read, just record the type.
93	    return { text: "", title: undefined };
94	  }
95	
96	  const html = (await res.text()).slice(0, 2_000_000);
97	
98	  const title =
99	    meta(html, [
100	      /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
101	      /<meta[^>]+name=["']twitter:title["'][^>]+content=["']([^"']+)["']/i,
102	      /<title[^>]*>([\s\S]*?)<\/title>/i,
103	    ]) || undefined;
104	
105	  const description = meta(html, [
106	    /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']+)["']/i,
107	    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i,
108	  ]);
109	
110	  const ogImage = absolutize(
111	    meta(html, [/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i]),
112	    finalUrl
113	  );
114	
115	  const favicon =
116	    absolutize(
117	      html.match(/<link[^>]+rel=["'][^"']*icon[^"']*["'][^>]+href=["']([^"']+)["']/i)?.[1],
118	      finalUrl
119	    ) ?? absolutize("/favicon.ico", finalUrl);
120	
